/* SPDX-License-Identifier: GPL-3.0-or-later
 * kodeos role only. TEMPORARY STAND-IN for kdrv_fs.c (the internal FAT volume, mounted at "/storage").
 *
 * kdrv_storage.c above it uses plain stdio/dirent on the mount point, so a mount that fills Emscripten's in-memory
 * file system with the factory content is enough: kdrv_storage, AO_Storage and everything above run unmodified.
 * Content comes from build/kodeos/gen/kodeos_factory.c, generated by `dotbench build --role kodeos` from what
 * kodeOS's own CMakeLists.txt stages into the FAT image: Kody's pack in kode/ and storage_image/ (minus README and
 * *.commit). The same tree is packaged as factory/storage/** in kodeos.dotbench.
 *
 * Limits of this stand-in: not persistent (every boot starts from the factory content; writes are lost on reload),
 * no FAT semantics (8.3/long names, 2 MB capacity is only REPORTED), no formatting.
 *
 * Replaced by: the storage engineer (FAT volume + factory content applied once, persisted). When their kdrv_fs
 * fake exists, delete this file; the generated factory blob can be dropped too. */
#include <errno.h>
#include <stdio.h>
#include <string.h>
#include <sys/stat.h>
#include <pthread.h>
#include "kdrv_fs.h"
#include "kodeos_factory.h"

#define MOUNT "/storage"
#define VOLUME_BYTES (2016u * 1024u)    /* "holds about 2,016 KB" (storage_image/README.md) */

static pthread_mutex_t g_mu = PTHREAD_MUTEX_INITIALIZER;
static bool g_mounted;
static bool g_populated;
static uint64_t g_used;

static void mkdirs(char *path)
{
    for (char *p = path + 1; *p; p++) {
        if (*p == '/') { *p = 0; mkdir(path, 0777); *p = '/'; }
    }
}

static void populate(void)
{
    mkdir(MOUNT, 0777);
    for (unsigned i = 0; i < kodeos_factory_count; i++) {
        const kodeos_factory_file_t *f = &kodeos_factory_files[i];
        char path[256];
        snprintf(path, sizeof path, MOUNT "/%s", f->path);
        mkdirs(path);
        FILE *fp = fopen(path, "wb");
        if (!fp) continue;
        fwrite(f->data, 1, f->size, fp);
        fclose(fp);
        g_used += f->size;
    }
}

const char *kdrv_fs_mount(void)
{
    pthread_mutex_lock(&g_mu);
    if (!g_populated) { populate(); g_populated = true; }
    g_mounted = true;
    pthread_mutex_unlock(&g_mu);
    return MOUNT;
}
void kdrv_fs_unmount(void) { pthread_mutex_lock(&g_mu); g_mounted = false; pthread_mutex_unlock(&g_mu); }
bool kdrv_fs_mounted(void) { return g_mounted; }
const char *kdrv_fs_mount_point(void) { return MOUNT; }
kode_status_t kdrv_fs_usage(uint64_t *total, uint64_t *free_bytes)
{
    if (!g_mounted) return KODE_ERROR;
    if (total) *total = VOLUME_BYTES;
    if (free_bytes) *free_bytes = g_used < VOLUME_BYTES ? VOLUME_BYTES - g_used : 0;
    return KODE_OK;
}
uint32_t kdrv_fs_cluster_bytes(void) { return g_mounted ? 4096u : 0u; }
